import { join } from "node:path";

/**
 * The prepped first-session table (DESIGN.md §8.4, repeat playtests;
 * M6-D29): the table as the walkthrough's `runPrep` leaves it after step 6,
 * saved by the host, with its assets directory beside it as the host stores
 * them (`<file>.assets/<slug>-<hash8>.<ext>`). Copy both, keeping the
 * assets directory's name, and `pnpm start` the copy to begin at step 7.
 * Regenerated by `pnpm fixtures:prepped` (packages/ui/test/walkthrough/prepped-table.test.tsx).
 */
export const PREPPED_TABLE: {
  readonly file: "first-session.table.json";
  readonly assetsDir: "first-session.table.json.assets";
} = { file: "first-session.table.json", assetsDir: "first-session.table.json.assets" };

/** The directory holding the prepped table and its assets directory: `packages/fixtures/examples/`. */
export function examplesDir(): string {
  return join(import.meta.dirname, "..", "examples");
}

/** The absolute path of the prepped first-session table file. */
export function preppedTablePath(): string {
  return join(examplesDir(), PREPPED_TABLE.file);
}
